require 'config.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='toggle_user'&&$id!==$_SESSION['user_id']){$s=db()->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=? AND role='user'");$s->execute([$id]);flash('User status updated.');}
 if($action==='toggle_product'&&$id>0){$s=db()->prepare("UPDATE products SET active=IF(active=1,0,1) WHERE id=?");$s->execute([$id]);flash('Product visibility updated.');}
 if($action==='delete_message'&&$id>0){$s=db()->prepare("DELETE FROM contact_messages WHERE id=?");$s->execute([$id]);flash('Message deleted.');}
 redirect('admin_dashboard.php'.(!empty($_POST['view'])?'?view='.urlencode($_POST['view']):''));
}
